import { beforeEach, describe, expect, it } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { seedDatabase } from '../src/seed/index.js';

describe('cx_001: refundedTotal must never exceed order total', () => {
  beforeEach(async () => {
    await seedDatabase();
  });

  it('rejects an admin refund on a fully-refunded cancelled order', async () => {
    // Set up admin token
    const adminLogin = await request(app)
      .post('/api/auth/login')
      .send({
        email: 'admin@kettleandcrate.com',
        password: 'admin-pass'
      });
    const adminToken = adminLogin.body.token;

    // Step 1: create a product at price 500 with stock 1
    const productRes = await request(app)
      .post('/api/products')
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        name: 'Regression Product',
        description: 'A quality home goods item.',
        category: 'cookware',
        price: 500,
        stock: 1
      });
    expect(productRes.status).toBe(201);
    const productId = productRes.body.id;

    // Step 2: customer places an order for qty 1
    const signupRes = await request(app)
      .post('/api/auth/signup')
      .send({
        name: 'Test User',
        email: 'cx001.user@example.com',
        password: 'pass-cx001'
      });
    expect(signupRes.status).toBe(201);
    const customerToken = signupRes.body.token;

    const orderRes = await request(app)
      .post('/api/orders')
      .set('Authorization', `Bearer ${customerToken}`)
      .send({
        items: [{ productId, qty: 1 }],
        shippingAddress: {
          name: 'Test User',
          line1: '123 Main St',
          city: 'Springfield',
          region: 'IL',
          postcode: '62701',
          country: 'US'
        }
      });
    expect(orderRes.status).toBe(201);
    const orderId = orderRes.body.id;
    const orderTotal = orderRes.body.total;

    // Step 3: customer cancels the order — refundedTotal becomes equal to total
    const cancelRes = await request(app)
      .post(`/api/orders/${orderId}/cancel`)
      .set('Authorization', `Bearer ${customerToken}`);
    expect(cancelRes.status).toBe(200);
    expect(cancelRes.body.refundedTotal).toBe(orderTotal);

    // Step 4: admin attempts a further refund of 100 on the already-fully-refunded order
    // This must be rejected because refundedTotal already equals total (no remaining balance)
    const refundRes = await request(app)
      .post(`/api/orders/${orderId}/refunds`)
      .set('Authorization', `Bearer ${adminToken}`)
      .send({
        amount: 100,
        reason: 'Administrative refund'
      });
    expect(refundRes.status).toBe(400);

    // Verify the invariant: refundedTotal must not exceed total
    const orderCheck = await request(app)
      .get(`/api/orders/${orderId}`)
      .set('Authorization', `Bearer ${customerToken}`);
    expect(orderCheck.status).toBe(200);
    expect(orderCheck.body.refundedTotal).toBeLessThanOrEqual(orderCheck.body.total);
  });
});
